// ---------------------------------------------------------------------------
// Automatic field / document classification per notification type
// ---------------------------------------------------------------------------
function autoFields(name, category) {
  const n = name.toLowerCase();
  if (category === 'Personnel') {
    if (n.includes('added')) return ['personName', 'role', 'effectiveDate', 'delegationLogUpdated', 'trainingCompleted', 'comments'];
    if (n.includes('removed')) return ['personName', 'role', 'effectiveDate', 'reason', 'delegationLogUpdated', 'comments'];
    return ['previousValue', 'newValue', 'effectiveDate', 'reason', 'irbRequired', 'regulatoryRequired', 'subjectsImpacted', 'comments'];
  }
  if (category === 'Site') {
    if (n.includes('temporarily closed')) return ['reason', 'startDate', 'endDate', 'subjectsAffected', 'comments'];
    if (n.includes('reopened')) return ['effectiveDate', 'reason', 'comments'];
    if (n.includes('expansion') || n.includes('new facility') || n.includes('satellite')) return ['facilityName', 'effectiveDate', 'description', 'equipmentDetails', 'comments'];
    if (n.includes('equipment')) return ['facilityName', 'equipmentDetails', 'effectiveDate', 'comments'];
    return ['previousValue', 'newValue', 'effectiveDate', 'reason', 'irbRequired', 'regulatoryRequired', 'comments'];
  }
  if (category === 'Study') {
    if (n.includes('hold')) return ['reason', 'startDate', 'endDate', 'sponsorApproval', 'subjectsAffected', 'enrollmentStatus', 'impImpact', 'safetyImpact'];
    if (n.includes('restart')) return ['effectiveDate', 'sponsorApproval', 'enrollmentStatus', 'comments'];
    if (n.includes('dsmb')) return ['milestoneDate', 'description', 'actionTaken', 'reportedToAuthority', 'comments'];
    if (n.includes('sponsor contact')) return ['previousValue', 'newValue', 'effectiveDate', 'comments'];
    if (n.includes('administrative')) return ['description', 'effectiveDate', 'comments'];
    return ['milestoneDate', 'subjectsEnrolledToDate', 'comments'];
  }
  if (category === 'Safety') return ['description', 'severityGrade', 'startDate', 'actionTaken', 'subjectsAffected', 'reportedToAuthority', 'comments'];
  if (category === 'Laboratory') {
    if (n.includes('closure')) return ['reason', 'startDate', 'endDate', 'comments'];
    if (n.includes('calibration') || n.includes('reference range')) return ['facilityName', 'effectiveDate', 'description', 'comments'];
    return ['previousValue', 'newValue', 'effectiveDate', 'reason', 'comments'];
  }
  if (category === 'Pharmacy') {
    if (n.includes('closure')) return ['reason', 'startDate', 'endDate', 'comments'];
    if (n.includes('temperature excursion')) return ['storageLocation', 'excursionRange', 'excursionDuration', 'startDate', 'actionTaken', 'comments'];
    if (n.includes('shipment delay')) return ['delayDays', 'startDate', 'reason', 'impImpact', 'comments'];
    if (n.includes('storage location')) return ['storageLocation', 'effectiveDate', 'reason', 'comments'];
    if (n.includes('new pharmacist')) return ['personName', 'effectiveDate', 'comments'];
    return ['previousValue', 'newValue', 'effectiveDate', 'reason', 'comments'];
  }
  if (category === 'Vendor') return ['previousValue', 'newValue', 'effectiveDate', 'reason', 'transitionPlan', 'comments'];
  if (category === 'Regulatory') return ['effectiveDate', 'description', 'regulatoryRequired', 'comments'];
  if (category === 'Administrative') return ['description', 'effectiveDate', 'comments'];
  return ['description', 'comments'];
}

function autoDocuments(name, category) {
  const n = name.toLowerCase();
  if (category === 'Personnel') {
    if (n.includes('added')) return ['Notification Letter', 'CV', 'GCP Certificate', 'Medical License', 'Delegation Log'];
    if (n.includes('removed')) return ['Notification Letter', 'Delegation Log Update'];
    return ['Notification Letter', 'Updated CV', 'Delegation Log'];
  }
  if (category === 'Site') {
    if (n.includes('temporarily closed')) return ['Closure Notification Letter', 'Subject Transfer Plan'];
    if (n.includes('reopened')) return ['Reopening Notification Letter', 'Facility Readiness Confirmation'];
    if (n.includes('expansion') || n.includes('new facility') || n.includes('satellite')) return ['Facility Notification Letter', 'Facility Inspection Report', 'Equipment List'];
    return ['Notification Letter', 'Updated Site Information Form'];
  }
  if (category === 'Study') {
    if (n.includes('hold')) return ['Sponsor Letter', 'Hold Justification', 'Risk Assessment', 'Safety Assessment', 'Subject Communication', 'IMP Management Plan'];
    if (n.includes('restart')) return ['Restart Notification Letter', 'Sponsor Approval'];
    if (n.includes('dsmb')) return ['DSMB Recommendation Letter', 'Sponsor Response'];
    return ['Milestone Notification Letter'];
  }
  if (category === 'Safety') {
    if (n.includes('susar')) return ['SUSAR Report Form', 'Investigator Notification Letter', 'Regulatory Submission Confirmation'];
    return ['Safety Notification Letter', 'Event Description Report'];
  }
  if (category === 'Laboratory') {
    if (n.includes('closure')) return ['Closure Notification Letter', 'Sample Transfer Plan'];
    return ['Notification Letter', 'Updated Lab Certification'];
  }
  if (category === 'Pharmacy') {
    if (n.includes('closure')) return ['Closure Notification Letter', 'IMP Transfer Plan'];
    if (n.includes('temperature excursion')) return ['Excursion Report', 'Temperature Log', 'IMP Impact Assessment'];
    return ['Notification Letter'];
  }
  if (category === 'Vendor') return ['Notification Letter', 'Vendor Qualification Documentation', 'Transition Plan'];
  if (category === 'Regulatory') return ['Notification Letter', 'Supporting Regulatory Documentation'];
  return ['Notification Letter'];
}

// Build the full notification type registry once.
const NOTIFICATION_TYPES = (() => {
  const types = [];
  let counter = 0;
  NOTIFICATION_CATEGORIES.forEach((cat) => {
    cat.names.forEach((name) => {
      counter += 1;
      types.push({
        id: `NTYPE-${String(counter).padStart(3, '0')}`,
        category: cat.id,
        name,
        fields: autoFields(name, cat.id),
        fieldLabelOverrides: {},
        documents: autoDocuments(name, cat.id),
        dueDays: DUE_DAYS_BY_CATEGORY[cat.id],
      });
    });
  });
  const byName = (n) => types.find((t) => t.name === n);
  Object.assign(byName('Principal Investigator Change'), {
    fieldLabelOverrides: { previousValue: 'Current PI', newValue: 'New PI' },
    documents: ['Notification Letter', 'Updated CV', 'Medical License', 'GCP Certificate', 'Financial Disclosure', 'Delegation Log', 'PI Signature', 'Sponsor Approval'],
  });
  Object.assign(byName('Temporary Study Hold'), {
    fieldLabelOverrides: { endDate: 'Expected Resume Date' },
  });
  Object.assign(byName('Study Coordinator Added'), {
    fieldLabelOverrides: { personName: 'Coordinator Name' },
  });
  return types;
})();

// ---------------------------------------------------------------------------
// Registry loading — the categories/types/field library live in MongoDB
// (GET /notification-templates, auto-seeded from the constants above). The
// constants remain as an offline fallback so the wizard still works if the
// endpoint is unreachable.
// ---------------------------------------------------------------------------
const CATEGORY_ICON_MAP = {
  Personnel: Users,
  Site: Building2,
  Study: BookOpen,
  Safety: ShieldAlert,
  Laboratory: FlaskConical,
  Pharmacy: Pill,
  Vendor: Truck,
  Regulatory: Landmark,
  Administrative: Briefcase,
  Other: MoreHorizontal,
};

const DEFAULT_REGISTRY = {
  categories: NOTIFICATION_CATEGORIES,
  types: NOTIFICATION_TYPES,
  fieldLibrary: FIELD_LIBRARY,
};

function normalizeRegistry(data) {
  const rawTypes = Array.isArray(data?.types) ? data.types : [];
  const rawCategories = Array.isArray(data?.categories) ? data.categories : [];
  if (!rawTypes.length || !rawCategories.length) return DEFAULT_REGISTRY;
  const types = rawTypes.map((t) => ({
    ...t,
    id: t.id || t.typeId,
    fieldLabelOverrides: t.fieldLabelOverrides || {},
    documents: t.documents || [],
    fields: t.fields || [],
  }));
  const categories = rawCategories.map((c) => ({
    id: c.id,
    color: c.color || 'blue',
    icon: CATEGORY_ICON_MAP[c.id] || MoreHorizontal,
  }));
  const fieldLibrary =
    data?.fieldLibrary && Object.keys(data.fieldLibrary).length ? data.fieldLibrary : FIELD_LIBRARY;
  return { categories, types, fieldLibrary };
}

let _registryCache = null;
let _registryPromise = null;
function loadNotificationRegistry() {
  if (_registryCache) return Promise.resolve(_registryCache);
  if (!_registryPromise) {
    _registryPromise = sitePackageService
      .getNotificationTemplates()
      .then((resp) => {
        _registryCache = normalizeRegistry(resp?.data || resp);
        return _registryCache;
      })
      .catch((err) => {
        console.warn('[NotificationWizard] Falling back to built-in templates:', err?.message);
        _registryPromise = null; // allow retry on next mount
        return DEFAULT_REGISTRY;
      });
  }
  return _registryPromise;
}

// ---------------------------------------------------------------------------
// Draft persistence (browser refresh / tab navigation safety).
// Same IndexedDB database + store as the classic CreateSitePackageForm.
// File objects are structured-cloneable, so staged local files survive too.
// ---------------------------------------------------------------------------
const DRAFT_DB_NAME = 'crm_site_packages';
const DRAFT_STORE = 'drafts';

const openDraftDb = () =>
  new Promise((resolve, reject) => {
    try {
      const req = indexedDB.open(DRAFT_DB_NAME, 1);
      req.onupgradeneeded = () => {
        const db = req.result;
        if (!db.objectStoreNames.contains(DRAFT_STORE)) {
          db.createObjectStore(DRAFT_STORE);
        }
      };
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => reject(req.error);
    } catch (e) {
      reject(e);
    }
  });

const draftDbGet = async (key) => {
  const db = await openDraftDb();
  return await new Promise((resolve, reject) => {
    const tx = db.transaction(DRAFT_STORE, 'readonly');
    const req = tx.objectStore(DRAFT_STORE).get(key);
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
    tx.oncomplete = () => db.close();
  });
};

const draftDbSet = async (key, value) => {
  const db = await openDraftDb();
  return await new Promise((resolve, reject) => {
    const tx = db.transaction(DRAFT_STORE, 'readwrite');
    const req = tx.objectStore(DRAFT_STORE).put(value, key);
    req.onsuccess = () => resolve(true);
    req.onerror = () => reject(req.error);
    tx.oncomplete = () => db.close();
  });
};

const draftDbDel = async (key) => {
  const db = await openDraftDb();
  return await new Promise((resolve, reject) => {
    const tx = db.transaction(DRAFT_STORE, 'readwrite');
    const req = tx.objectStore(DRAFT_STORE).delete(key);
    req.onsuccess = () => resolve(true);
    req.onerror = () => reject(req.error);
    tx.oncomplete = () => db.close();
  });
};

const wizardDraftKey = (studyId, siteId) =>
  `notification_wizard:${String(studyId || '').trim()}:${String(siteId || '').trim()}`;

const slugify = (value) =>
  String(value || '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '') || 'document';

const fieldLabelFor = (type, fieldKey, fieldLibrary = FIELD_LIBRARY) =>
  type?.fieldLabelOverrides?.[fieldKey] || fieldLibrary[fieldKey]?.label || fieldKey;

const fileNameFromUrl = (url) => {
  try {
    const seg = String(url || '').split('?')[0].split('/').pop() || '';
    return decodeURIComponent(seg);
  } catch {
    return '';
  }
};

/** Parse the structured notes text written by buildNotesText back into its parts. */
function parseNotificationNotes(notes) {
  const lines = String(notes || '').split('\n');
  let categoryName = null;
  let typeName = null;
  const detailLines = [];
  const extraLines = [];
  let section = 'head';
  for (const line of lines) {
    if (line.startsWith('--- Notification Details ---')) { section = 'details'; continue; }
    if (line.startsWith('--- Additional Notes ---')) { section = 'notes'; continue; }
    if (section === 'notes') { extraLines.push(line); continue; }
    const m = line.match(/^(.*?):\s?(.*)$/);
    if (m && m[1].trim() === 'Notification Category') { categoryName = m[2].trim(); continue; }
    if (m && m[1].trim() === 'Notification Type') { typeName = m[2].trim(); continue; }
    if (m && m[1].trim() === 'Response Timeline') continue;
    if (section === 'details' && line.trim()) detailLines.push(line);
  }
  return { categoryName, typeName, detailLines, extraNotes: extraLines.join('\n').trim() };
}

/** Rebuild the wizard's initial state from an existing Notification package. */
function buildInitialStateFromPackage(pkg, registry = DEFAULT_REGISTRY) {
  if (!pkg) return null;
  const allTypes = registry.types;
  const parsed = parseNotificationNotes(pkg.notes);
  const type =
    allTypes.find((t) => t.name === parsed.typeName && t.category === parsed.categoryName) ||
    allTypes.find((t) => t.name === parsed.typeName) ||
    null;

  const formData = {};
  if (type) {
    const labelToKey = new Map(type.fields.map((fk) => [fieldLabelFor(type, fk, registry.fieldLibrary), fk]));
    let lastKey = null;
    for (const line of parsed.detailLines) {
      const m = line.match(/^(.*?):\s?(.*)$/);
      const label = m ? m[1].trim() : null;
      if (label && labelToKey.has(label)) {
        lastKey = labelToKey.get(label);
        formData[lastKey] = m[2];
      } else if (lastKey) {
        // Continuation of a multi-line textarea value.
        formData[lastKey] = `${formData[lastKey]}\n${line}`;
      }
    }
  }

  const stagedDocs = {};
  (pkg.documents || []).forEach((d) => {
    if (!d?.name || !d?.fileUrl) return;
    stagedDocs[d.name] = {
      fileUrl: d.fileUrl,
      mimeType: d.mimeType,
      fileSize: d.fileSize,
      source: d.source,
      sourceDocumentId: d.sourceDocumentId,
      sourceTitle: d.sourceTitle || fileNameFromUrl(d.fileUrl),
      original: d,
    };
  });

  // Saved documents that aren't part of the type's standard set are user-added slots.
  const typeDocNames = new Set(type?.documents || []);
  const customDocNames = Object.keys(stagedDocs).filter((n) => !typeDocNames.has(n));

  return {
    categoryId: type?.category ?? parsed.categoryName ?? null,
    typeId: type?.id ?? null,
    formData,
    stagedDocs,
    customDocNames,
    packageName: pkg.packageName || '',
    priority: pkg.priority || 'Medium',
    expectedSubmissionDate: pkg.expectedSubmissionDate ? String(pkg.expectedSubmissionDate).slice(0, 10) : '',
    extraNotes: parsed.extraNotes,
  };
}

