const NotificationWizardInner = ({
  registry,
  studyId,
  siteId,
  studyName,
  siteName,
  irb,
  existingPackage = null,
  onBack,
  onCancel,
  onCreate,
  onSuccess,
}) => {
  const { toast } = useToast();
  const { categories: notificationCategories, types: notificationTypes, fieldLibrary } = registry;
  // Editing an existing package: rebuild wizard state from its saved data (once, on mount).
  const [initial] = useState(() => buildInitialStateFromPackage(existingPackage, registry));
  const isEditing = Boolean(existingPackage?._id || existingPackage?.id);
  const [step, setStep] = useState(1);
  const [categoryId, setCategoryId] = useState(initial?.categoryId ?? null);
  const [typeId, setTypeId] = useState(initial?.typeId ?? null);
  const [typeSearch, setTypeSearch] = useState('');
  const [formData, setFormData] = useState(initial?.formData ?? {});
  const [stagedDocs, setStagedDocs] = useState(initial?.stagedDocs ?? {}); // { [docName]: { file } | { fileUrl, ... } }
  const [customDocNames, setCustomDocNames] = useState(initial?.customDocNames ?? []);
  const [addDocOpen, setAddDocOpen] = useState(false);
  const [newDocName, setNewDocName] = useState('');
  const [packageName, setPackageName] = useState(initial?.packageName ?? '');
  const [priority, setPriority] = useState(initial?.priority ?? 'Medium');
  const [expectedSubmissionDate, setExpectedSubmissionDate] = useState(initial?.expectedSubmissionDate ?? '');
  const [notes, setNotes] = useState(initial?.extraNotes ?? '');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [uploadOverallProgress, setUploadOverallProgress] = useState(0);
  const [showISFBrowser, setShowISFBrowser] = useState(false);
  const [selectedDocForISF, setSelectedDocForISF] = useState(null);
  const [isfBrowserKey, setIsfBrowserKey] = useState(0);
  const fileInputRef = useRef(null);
  const pendingDocNameRef = useRef(null);

  // -------------------------------------------------------------------------
  // Draft persistence — new packages only. Editing an existing package always
  // prefills from the server, so drafts would fight the saved state.
  // -------------------------------------------------------------------------
  const draftKey = wizardDraftKey(studyId, siteId);
  const [draftLoaded, setDraftLoaded] = useState(false);

  useEffect(() => {
    if (isEditing || !studyId || !siteId) {
      setDraftLoaded(true);
      return undefined;
    }
    let cancelled = false;
    (async () => {
      try {
        const saved = await draftDbGet(draftKey);
        if (cancelled || !saved) return;
        // Only restore the type if it still exists in the registry.
        const savedType = saved.typeId ? notificationTypes.find((t) => t.id === saved.typeId) : null;
        if (saved.categoryId) setCategoryId(saved.categoryId);
        if (savedType) setTypeId(savedType.id);
        if (saved.formData && typeof saved.formData === 'object') setFormData(saved.formData);
        if (saved.stagedDocs && typeof saved.stagedDocs === 'object') setStagedDocs(saved.stagedDocs);
        if (Array.isArray(saved.customDocNames)) setCustomDocNames(saved.customDocNames);
        if (typeof saved.packageName === 'string' && saved.packageName) setPackageName(saved.packageName);
        if (saved.priority) setPriority(saved.priority);
        if (typeof saved.expectedSubmissionDate === 'string') setExpectedSubmissionDate(saved.expectedSubmissionDate);
        if (typeof saved.notes === 'string') setNotes(saved.notes);
        if (Number.isInteger(saved.step) && saved.step >= 1 && saved.step <= WIZARD_STEPS.length) {
          // Steps beyond 2 need a resolvable type.
          setStep(saved.step > 2 && !savedType ? (saved.categoryId ? 2 : 1) : saved.step);
        }
      } catch {
        // Drafts are best-effort.
      } finally {
        if (!cancelled) setDraftLoaded(true);
      }
    })();
    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    if (!draftLoaded || isEditing || !studyId || !siteId) return undefined;
    const handle = setTimeout(() => {
      draftDbSet(draftKey, {
        step,
        categoryId,
        typeId,
        formData,
        stagedDocs,
        customDocNames,
        packageName,
        priority,
        expectedSubmissionDate,
        notes,
        savedAt: new Date().toISOString(),
      }).catch(() => {});
    }, 350);
    return () => clearTimeout(handle);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [step, categoryId, typeId, formData, stagedDocs, customDocNames, packageName, priority, expectedSubmissionDate, notes, draftLoaded]);

  const clearDraft = async () => {
    try {
      await draftDbDel(draftKey);
    } catch {
      // ignore
    }
  };

  const selectedCategory = useMemo(
    () => notificationCategories.find((c) => c.id === categoryId) || null,
    [notificationCategories, categoryId]
  );
  const selectedType = useMemo(
    () => notificationTypes.find((t) => t.id === typeId) || null,
    [notificationTypes, typeId]
  );

  const typesForCategory = useMemo(() => {
    const list = notificationTypes.filter((t) => t.category === categoryId);
    const q = typeSearch.trim().toLowerCase();
    if (!q) return list;
    return list.filter((t) => t.name.toLowerCase().includes(q));
  }, [notificationTypes, categoryId, typeSearch]);

  const typeCountByCategory = useMemo(() => {
    const counts = {};
    notificationTypes.forEach((t) => {
      counts[t.category] = (counts[t.category] || 0) + 1;
    });
    return counts;
  }, [notificationTypes]);

  const fieldLabel = (type, fieldKey) => fieldLabelFor(type, fieldKey, fieldLibrary);

  // Standard documents for the selected type plus user-added slots.
  const documentsForType = useMemo(() => {
    const base = selectedType?.documents || [];
    const baseSet = new Set(base);
    return [...base, ...customDocNames.filter((n) => !baseSet.has(n))];
  }, [selectedType, customDocNames]);
  const customDocSet = useMemo(() => new Set(customDocNames), [customDocNames]);

  const docProgress = useMemo(() => {
    const uploaded = documentsForType.filter((d) => stagedDocs[d]?.file || stagedDocs[d]?.fileUrl).length;
    return {
      total: documentsForType.length,
      uploaded,
      percent: documentsForType.length ? Math.round((uploaded / documentsForType.length) * 100) : 0,
    };
  }, [documentsForType, stagedDocs]);

  const handleAddCustomDoc = () => {
    const trimmed = newDocName.trim();
    if (!trimmed) return;
    if (documentsForType.some((n) => n.toLowerCase() === trimmed.toLowerCase())) {
      toast({
        title: 'Duplicate document',
        description: `"${trimmed}" is already in the list.`,
        variant: 'destructive',
      });
      return;
    }
    setCustomDocNames((prev) => [...prev, trimmed]);
    setNewDocName('');
    setAddDocOpen(false);
  };

  const removeCustomDoc = (docName) => {
    setCustomDocNames((prev) => prev.filter((n) => n !== docName));
    setStagedDocs((prev) => {
      const next = { ...prev };
      delete next[docName];
      return next;
    });
  };

  const selectCategory = (id) => {
    if (id !== categoryId) {
      setTypeId(null);
      setFormData({});
      // Keep already-saved documents when editing — they stay on the package.
      if (!isEditing) {
        setStagedDocs({});
        setCustomDocNames([]);
      }
      setPackageName('');
    }
    setCategoryId(id);
    setTypeSearch('');
    setStep(2);
  };

  const selectType = (id) => {
    if (id !== typeId) {
      setFormData({});
      if (!isEditing) {
        setStagedDocs({});
        setCustomDocNames([]);
      }
      const t = notificationTypes.find((x) => x.id === id);
      setPackageName(t ? `Notification – ${t.name}` : '');
    }
    setTypeId(id);
  };

  const setField = (key, value) => setFormData((prev) => ({ ...prev, [key]: value }));

  const openFilePicker = (docName) => {
    pendingDocNameRef.current = docName;
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
      fileInputRef.current.click();
    }
  };

  const onFilePicked = (e) => {
    const file = e.target.files?.[0];
    const docName = pendingDocNameRef.current;
    pendingDocNameRef.current = null;
    if (!file || !docName) return;
    setStagedDocs((prev) => ({ ...prev, [docName]: { file } }));
  };

  const removeStagedDoc = (docName) => {
    setStagedDocs((prev) => {
      const next = { ...prev };
      delete next[docName];
      return next;
    });
  };

  const openISFBrowser = (docName) => {
    setSelectedDocForISF(docName);
    setShowISFBrowser(true);
  };

  const closeISFBrowser = () => {
    setShowISFBrowser(false);
    setSelectedDocForISF(null);
    setIsfBrowserKey((k) => k + 1);
  };

  const handleISFImport = async (documents) => {
    const picked = Array.isArray(documents) ? documents : [];
    if (!selectedDocForISF || picked.length === 0) return;
    if (picked.length > 1) {
      toast({
        title: 'Upload limit exceeded',
        description: `Only 1 file is allowed for ${selectedDocForISF}. Please select a single document.`,
        variant: 'destructive',
      });
      return;
    }
    const doc = picked[0];
    // ISF docs already live in Azure; store a reference instead of re-uploading.
    setStagedDocs((prev) => ({
      ...prev,
      [selectedDocForISF]: {
        source: 'ISF',
        sourceDocumentId: doc.id,
        sourceTitle: doc.title,
        sourceUrl: doc.url,
        fileUrl: doc.url,
        mimeType: doc.mime_type || 'application/pdf',
        fileSize: doc.fileSize || 0,
      },
    }));
    toast({ title: 'Imported from ISF', description: `${doc.title} attached to ${selectedDocForISF}.` });
    closeISFBrowser();
  };

  const handleNext = () => {
    if (step === 2 && !typeId) {
      toast({
        title: 'Notification type required',
        description: 'Select a notification type to continue.',
        variant: 'destructive',
      });
      return;
    }
    setStep((s) => Math.min(WIZARD_STEPS.length, s + 1));
  };

  const handlePrevious = () => {
    if (step === 1) {
      onBack?.();
      return;
    }
    setStep((s) => s - 1);
  };

  const buildNotesText = () => {
    const lines = [
      `Notification Category: ${selectedType.category}`,
      `Notification Type: ${selectedType.name}`,
      `Response Timeline: ${selectedType.dueDays} days`,
      '',
      '--- Notification Details ---',
    ];
    selectedType.fields.forEach((fk) => {
      const v = formData[fk];
      if (v !== undefined && v !== null && String(v).trim() !== '') {
        lines.push(`${fieldLabel(selectedType, fk)}: ${v}`);
      }
    });
    const extra = notes.trim();
    if (extra) {
      lines.push('', '--- Additional Notes ---', extra);
    }
    return lines.join('\n');
  };

  const handleCreate = async () => {
    if (!selectedType) return;
    if (!studyId || !siteId) {
      toast({
        title: 'Study and site required',
        description: 'Choose a study and site in the dashboard header first.',
        variant: 'destructive',
      });
      return;
    }
    if (!irb?.id) {
      toast({
        title: 'No IRB mapped',
        description: 'Select an IRB in Site Profile for this site, then return here.',
        variant: 'destructive',
      });
      return;
    }
    setIsSubmitting(true);
    setUploadOverallProgress(0);
    try {
      // 1) Build documents payload — upload local files; ISF imports are already in Azure.
      const documentsPayload = [];
      const localEntries = Object.entries(stagedDocs).filter(([, v]) => v?.file && v?.source !== 'ISF');
      let uploadedCount = 0;
      for (const [docName, row] of Object.entries(stagedDocs)) {
        const docTypeKey = slugify(docName);
        // Documents already saved on the package: pass through unchanged.
        if (row?.original && !row?.file) {
          documentsPayload.push({ ...row.original });
          continue;
        }
        if (row?.source === 'ISF' && row?.fileUrl) {
          documentsPayload.push({
            name: docName,
            fileUrl: row.fileUrl,
            fileSize: row.fileSize || 0,
            mimeType: row.mimeType || 'application/pdf',
            source: 'ISF',
            ...(row.sourceDocumentId ? { sourceDocumentId: row.sourceDocumentId } : {}),
            ...(row.sourceTitle ? { sourceTitle: row.sourceTitle } : {}),
            type: docTypeKey,
          });
          continue;
        }
        if (!row?.file) continue;
        const resp = await sitePackageService.uploadFile(
          row.file,
          String(studyId),
          String(siteId),
          docTypeKey
        );
        const fileInfo = resp?.data || resp;
        if (!fileInfo?.fileUrl) throw new Error(`Upload failed for ${docName}`);
        uploadedCount += 1;
        if (localEntries.length > 0) {
          setUploadOverallProgress(Math.round((uploadedCount / localEntries.length) * 100));
        }
        documentsPayload.push({
          name: docName,
          fileUrl: fileInfo.fileUrl,
          fileSize: fileInfo.fileSize || row.file.size || 0,
          mimeType: fileInfo.mimeType || row.file.type || 'application/octet-stream',
          source: 'upload',
          type: docTypeKey,
        });
      }

      // 2) Create or update the package
      const commonFields = {
        irb_id: irb.id,
        ethicsBoard: irb.name,
        packageName: packageName || `Notification – ${selectedType.name}`,
        description: `${selectedType.category} notification — ${selectedType.name}`,
        priority,
        submissionType: 'Notification',
        expectedSubmissionDate: expectedSubmissionDate || null,
        contactPerson: {},
        notes: buildNotesText(),
        documents: documentsPayload,
      };

      if (isEditing) {
        const pkgId = existingPackage._id || existingPackage.id;
        const updateResp = await sitePackageService.update(pkgId, commonFields, {
          study: String(studyId),
          site: String(siteId),
        });
        if (updateResp?.success === false) {
          throw new Error(updateResp?.error || 'Failed to update notification package');
        }
        toast({ title: 'Saved', description: `Notification package updated (${selectedType.name}).` });
      } else {
        const payload = { study: studyId, site: siteId, ...commonFields };
        const createResp = await onCreate(payload);
        const created = createResp?.data?.sitePackage || createResp?.sitePackage || createResp?.data;
        if (!created?._id) {
          throw new Error('Failed to create notification package: no package ID returned');
        }
        toast({ title: 'Success', description: `Notification package created (${selectedType.name}).` });
      }
      await clearDraft();
      onSuccess?.();
    } catch (error) {
      const data = error?.response?.data;
      let detail =
        (typeof data?.error === 'string' && data.error) ||
        (typeof data?.detail === 'string' && data.detail) ||
        error?.message ||
        'Failed to create notification package';
      if (Array.isArray(data?.detail)) {
        detail = data.detail.map((x) => (typeof x === 'string' ? x : x?.msg || JSON.stringify(x))).join(', ');
      }
      toast({ title: 'Error', description: detail, variant: 'destructive' });
    } finally {
      setIsSubmitting(false);
    }
  };

  // -------------------------------------------------------------------------
  // Step renderers
  // -------------------------------------------------------------------------
  const renderStepHeading = (badgeIcon, badgeText, title, subtitle) => {
    const BadgeIcon = badgeIcon;
    return (
      <div className="flex items-center gap-3.5 pb-5 mb-6 border-b border-slate-100 dark:border-slate-800">
        <div className="w-11 h-11 rounded-xl bg-gradient-to-br from-blue-600 to-indigo-600 text-white flex items-center justify-center shadow-md shadow-blue-500/25 shrink-0">
          <BadgeIcon className="w-5 h-5" />
        </div>
        <div className="min-w-0 flex-1">
          <h3 className="text-lg font-bold tracking-tight text-slate-900 dark:text-slate-50 leading-tight truncate">
            {title}
          </h3>
          <p className="text-sm text-slate-500 dark:text-slate-400 mt-0.5 truncate">{subtitle}</p>
        </div>
        {badgeText ? (
          <div className="hidden sm:inline-flex items-center px-2.5 py-1 rounded-full bg-blue-50 dark:bg-blue-950/40 border border-blue-100 dark:border-blue-900 text-blue-600 dark:text-blue-400 text-xs font-semibold shrink-0 max-w-[220px]">
            <span className="truncate">{badgeText}</span>
          </div>
        ) : null}
      </div>
    );
  };

  const renderStep1_category = () => (
    <div className="space-y-6">
      {renderStepHeading(ClipboardList, null, 'Select Category', 'Pick a category to see a focused list of notification types.')}
      <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-4">
        {notificationCategories.map((cat, idx) => {
          const isSelected = categoryId === cat.id;
          const colors = CATEGORY_COLOR_CLASSES[cat.color] || CATEGORY_COLOR_CLASSES.blue;
          const Icon = cat.icon;
          return (
            <Card
              key={cat.id}
              role="button"
              tabIndex={0}
              onKeyDown={(e) => {
                if (e.key === 'Enter' || e.key === ' ') {
                  e.preventDefault();
                  selectCategory(cat.id);
                }
              }}
              style={{ animationDelay: `${idx * 40}ms`, animationFillMode: 'backwards' }}
              className={cn(
                'group border-2 cursor-pointer rounded-2xl text-center transition-all duration-300 ease-out hover:shadow-xl hover:-translate-y-1',
                'animate-in fade-in slide-in-from-bottom-3 duration-500',
                'focus:outline-none focus-visible:ring-4 focus-visible:ring-blue-500/30',
                isSelected
                  ? cn(colors.border, colors.bg, 'shadow-lg')
                  : 'border-slate-200 dark:border-slate-700 hover:border-slate-300 dark:hover:border-slate-600 bg-white dark:bg-slate-900'
              )}
              onClick={() => selectCategory(cat.id)}
            >
              <CardContent className="p-5 flex flex-col items-center gap-3">
                <div
                  className={cn(
                    'w-12 h-12 rounded-2xl flex items-center justify-center transition-all duration-300',
                    isSelected ? cn(colors.icon, 'shadow-lg scale-105') : colors.iconIdle
                  )}
                >
                  <Icon className="w-5 h-5" />
                </div>
                <div>
                  <div className="text-sm font-bold text-slate-900 dark:text-slate-50">{cat.id}</div>
                  <div className="text-xs text-slate-500 dark:text-slate-400 mt-0.5">
                    {typeCountByCategory[cat.id] || 0} notification type{(typeCountByCategory[cat.id] || 0) === 1 ? '' : 's'}
                  </div>
                </div>
              </CardContent>
            </Card>
          );
        })}
      </div>
    </div>
  );

  const renderStep2_type = () => (
    <div className="space-y-6">
      {renderStepHeading(selectedCategory?.icon || FileText, selectedCategory?.id || 'Category', 'Select Notification Type', `Choose the ${selectedCategory?.id?.toLowerCase() || ''} notification you are reporting.`)}
      <div className="relative max-w-2xl mx-auto">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
        <Input
          value={typeSearch}
          onChange={(e) => setTypeSearch(e.target.value)}
          placeholder={`Search ${selectedCategory?.id || ''} notification types…`}
          className="pl-9"
        />
      </div>
      <div className="max-w-2xl mx-auto space-y-2">
        {typesForCategory.map((t) => {
          const isSelected = typeId === t.id;
          return (
            <div
              key={t.id}
              role="button"
              tabIndex={0}
              onKeyDown={(e) => {
                if (e.key === 'Enter' || e.key === ' ') {
                  e.preventDefault();
                  selectType(t.id);
                }
              }}
              onClick={() => selectType(t.id)}
              className={cn(
                'flex items-center gap-3 px-4 py-3 rounded-xl border-2 cursor-pointer transition-all',
                'focus:outline-none focus-visible:ring-4 focus-visible:ring-blue-500/30',
                isSelected
                  ? 'border-blue-500 bg-blue-50 dark:bg-blue-950/30 shadow-sm'
                  : 'border-slate-200 dark:border-slate-700 hover:border-blue-300 dark:hover:border-blue-700 bg-white dark:bg-slate-900'
              )}
            >
              <div
                className={cn(
                  'w-4 h-4 rounded-full border-2 flex items-center justify-center shrink-0',
                  isSelected ? 'border-blue-600' : 'border-slate-300 dark:border-slate-600'
                )}
              >
                {isSelected ? <div className="w-2 h-2 rounded-full bg-blue-600" /> : null}
              </div>
              <div className="flex-1 text-sm font-semibold text-slate-900 dark:text-slate-50">{t.name}</div>
              <Badge variant="outline" className="text-[11px] font-mono shrink-0">
                {t.dueDays}-day timeline
              </Badge>
              <CheckCircle2
                className={cn('w-5 h-5 shrink-0 transition-all', isSelected ? 'text-blue-600 opacity-100' : 'opacity-0')}
              />
            </div>
          );
        })}
        {typesForCategory.length === 0 ? (
          <div className="text-center text-sm text-slate-500 py-8">No notification types match your search.</div>
        ) : null}
      </div>
      {!typeId ? (
        <div className="max-w-2xl mx-auto flex items-center justify-center gap-2 text-sm text-amber-800 dark:text-amber-300 bg-amber-50/80 dark:bg-amber-950/30 border border-amber-200 dark:border-amber-900 rounded-xl px-4 py-3">
          <AlertCircle className="w-4 h-4 shrink-0" />
          Select one notification type to continue.
        </div>
      ) : (
        <div className="max-w-2xl mx-auto flex items-center justify-center gap-2 text-sm text-emerald-800 dark:text-emerald-300 bg-emerald-50/80 dark:bg-emerald-950/30 border border-emerald-200 dark:border-emerald-900 rounded-xl px-4 py-3">
          <CheckCircle2 className="w-4 h-4 shrink-0" />
          <span>
            <span className="font-semibold">{selectedType?.name}</span> selected — click Next to continue.
          </span>
        </div>
      )}
    </div>
  );

  const renderScopeItem = (Icon, label, value, span2 = false) => (
    <div className={cn('flex items-start gap-3 min-w-0', span2 && 'md:col-span-2')}>
      <div className="w-10 h-10 rounded-xl bg-white dark:bg-slate-900 border border-blue-100 dark:border-blue-900/50 flex items-center justify-center text-blue-600 dark:text-blue-400 shrink-0 shadow-sm">
        <Icon className="w-[18px] h-[18px]" />
      </div>
      <div className="min-w-0">
        <div className="text-[10.5px] font-bold uppercase tracking-wider text-slate-400 dark:text-slate-500">{label}</div>
        <div className="text-sm font-semibold text-slate-900 dark:text-slate-50 mt-0.5 break-words leading-snug">{value}</div>
      </div>
    </div>
  );

  const fieldLabelClass = 'text-xs font-semibold text-slate-600 dark:text-slate-300';

  const renderStep3_context = () => (
    <div className="space-y-6">
      {renderStepHeading(Building2, selectedType?.name, 'Study & Site Context', 'Scoped to the study and site selected in the dashboard header.')}
      <div className="max-w-3xl mx-auto space-y-5">
        {/* Submission scope panel (read-only) */}
        <div className="rounded-2xl border border-blue-100 dark:border-blue-900/40 bg-gradient-to-br from-blue-50/80 via-indigo-50/40 to-transparent dark:from-blue-950/30 dark:via-indigo-950/15 dark:to-transparent p-5 sm:p-6">
          <div className="flex items-center gap-1.5 text-[11px] font-bold uppercase tracking-wider text-blue-600 dark:text-blue-400 mb-5">
            <Landmark className="w-3.5 h-3.5" />
            Submission Scope
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
            {renderScopeItem(BookOpen, 'Study', studyName || studyId || '—')}
            {renderScopeItem(Building2, 'Site', siteName || siteId || '—')}
            {renderScopeItem(
              Landmark,
              'IRB / Ethics Board',
              irb?.name || <span className="text-amber-600 dark:text-amber-400">Not mapped — configure in Site Profile</span>,
              true
            )}
          </div>
        </div>

        {/* Package details */}
        <Card className="border-slate-200 dark:border-slate-700 rounded-2xl overflow-hidden shadow-sm">
          <div className="px-5 sm:px-6 py-4 border-b border-slate-100 dark:border-slate-800 bg-slate-50/70 dark:bg-slate-800/40 flex items-center gap-3">
            <div className="w-9 h-9 rounded-lg bg-blue-600 text-white flex items-center justify-center shadow-sm shadow-blue-500/30 shrink-0">
              <ClipboardList className="w-4 h-4" />
            </div>
            <div>
              <h4 className="text-sm font-bold text-slate-900 dark:text-slate-50 leading-tight">Package Details</h4>
              <p className="text-xs text-slate-500 dark:text-slate-400 mt-0.5">Name, priority, and planned submission date.</p>
            </div>
          </div>
          <CardContent className="p-5 sm:p-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
              <div className="space-y-1.5 md:col-span-2">
                <Label className={fieldLabelClass}>Package Name</Label>
                <Input
                  value={packageName}
                  onChange={(e) => setPackageName(e.target.value)}
                  placeholder="Package name"
                  className="h-10 rounded-lg focus-visible:ring-blue-500/30"
                />
              </div>
              <div className="space-y-1.5">
                <Label className={fieldLabelClass}>Priority</Label>
                <Select value={priority} onValueChange={setPriority}>
                  <SelectTrigger className="h-10 rounded-lg">
                    <SelectValue placeholder="Priority" />
                  </SelectTrigger>
                  <SelectContent>
                    {['Low', 'Medium', 'High', 'Urgent'].map((p) => (
                      <SelectItem key={p} value={p}>{p}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-1.5">
                <Label className={fieldLabelClass}>Expected Submission Date</Label>
                <Input
                  type="date"
                  value={expectedSubmissionDate}
                  onChange={(e) => setExpectedSubmissionDate(e.target.value)}
                  className="h-10 rounded-lg focus-visible:ring-blue-500/30"
                />
              </div>
            </div>
          </CardContent>
        </Card>

        {!irb?.id ? (
          <div className="rounded-xl border border-amber-200 bg-amber-50 p-4 text-amber-900 text-sm dark:border-amber-900 dark:bg-amber-950/30 dark:text-amber-300 flex items-start gap-2.5">
            <AlertCircle className="w-4 h-4 shrink-0 mt-0.5" />
            <div>
              <p className="font-semibold">No IRB mapped for this site</p>
              <p className="mt-1">
                Open <span className="font-semibold">Site Profile</span>, select an IRB, then return here. You can continue
                filling in the notification, but the package cannot be created until an IRB is mapped.
              </p>
            </div>
          </div>
        ) : null}
      </div>
    </div>
  );

  const renderField = (fieldKey) => {
    const def = fieldLibrary[fieldKey];
    if (!def) return null;
    const label = fieldLabel(selectedType, fieldKey);
    const value = formData[fieldKey] ?? '';
    const isWide = def.type === 'textarea';
    return (
      <div key={fieldKey} className={cn('space-y-1.5', isWide && 'md:col-span-2')}>
        <Label className={fieldLabelClass}>{label}</Label>
        {def.type === 'textarea' ? (
          <Textarea
            value={value}
            onChange={(e) => setField(fieldKey, e.target.value)}
            rows={3}
            placeholder={`Enter ${label.toLowerCase()}…`}
            className="rounded-lg resize-none focus-visible:ring-blue-500/30"
          />
        ) : def.type === 'yesno' ? (
          <Select value={value || undefined} onValueChange={(v) => setField(fieldKey, v)}>
            <SelectTrigger className="h-10 rounded-lg">
              <SelectValue placeholder="Select…" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="Yes">Yes</SelectItem>
              <SelectItem value="No">No</SelectItem>
            </SelectContent>
          </Select>
        ) : def.type === 'select' ? (
          <Select value={value || undefined} onValueChange={(v) => setField(fieldKey, v)}>
            <SelectTrigger className="h-10 rounded-lg">
              <SelectValue placeholder="Select…" />
            </SelectTrigger>
            <SelectContent>
              {(def.options || []).map((o) => (
                <SelectItem key={o} value={o}>{o}</SelectItem>
              ))}
            </SelectContent>
          </Select>
        ) : (
          <Input
            type={def.type === 'date' ? 'date' : def.type === 'number' ? 'number' : 'text'}
            value={value}
            onChange={(e) => setField(fieldKey, e.target.value)}
            placeholder={def.type === 'text' ? `Enter ${label.toLowerCase()}…` : undefined}
            className="h-10 rounded-lg focus-visible:ring-blue-500/30"
          />
        )}
      </div>
    );
  };

  const renderStep4_formAndDocs = () => (
    <div className="space-y-6">
      {renderStepHeading(FileText, selectedType?.name, 'Form & Documents', 'Fill in the details and attach supporting documents.')}
      <div className="grid grid-cols-1 lg:grid-cols-5 gap-6">
        {/* Dynamic form */}
        <Card className="lg:col-span-3 border-slate-200 dark:border-slate-700 rounded-2xl overflow-hidden shadow-sm h-fit">
          <div className="px-5 sm:px-6 py-4 border-b border-slate-100 dark:border-slate-800 bg-slate-50/70 dark:bg-slate-800/40 flex items-center gap-3">
            <div className="w-9 h-9 rounded-lg bg-blue-600 text-white flex items-center justify-center shadow-sm shadow-blue-500/30 shrink-0">
              <FileText className="w-4 h-4" />
            </div>
            <div className="min-w-0">
              <h4 className="text-sm font-bold text-slate-900 dark:text-slate-50 leading-tight truncate">
                {selectedType?.name}
              </h4>
              <p className="text-xs text-slate-500 dark:text-slate-400 mt-0.5">Notification details</p>
            </div>
          </div>
          <CardContent className="p-5 sm:p-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
              {(selectedType?.fields || []).map((fk) => renderField(fk))}
            </div>
          </CardContent>
        </Card>
        {/* Document checklist */}
        <Card className="lg:col-span-2 border-slate-200 dark:border-slate-700 rounded-2xl overflow-hidden shadow-sm h-fit">
          <div className="px-5 py-4 border-b border-slate-100 dark:border-slate-800 bg-slate-50/70 dark:bg-slate-800/40 flex items-center gap-3">
            <div className="w-9 h-9 rounded-lg bg-emerald-600 text-white flex items-center justify-center shadow-sm shadow-emerald-500/30 shrink-0">
              <FolderSearch className="w-4 h-4" />
            </div>
            <div className="flex-1 min-w-0">
              <h4 className="text-sm font-bold text-slate-900 dark:text-slate-50 leading-tight">Supporting Documents</h4>
              <p className="text-xs text-slate-500 dark:text-slate-400 mt-0.5">
                {docProgress.uploaded} of {docProgress.total} attached
              </p>
            </div>
            <Badge
              variant="outline"
              className={cn(
                'text-[11px] font-mono shrink-0',
                docProgress.uploaded === docProgress.total
                  ? 'border-emerald-300 text-emerald-700 bg-emerald-50 dark:border-emerald-800 dark:text-emerald-400 dark:bg-emerald-950/30'
                  : 'border-slate-200 text-slate-500 dark:border-slate-700 dark:text-slate-400'
              )}
            >
              {docProgress.percent}%
            </Badge>
          </div>
          <CardContent className="p-5">
            <Progress value={docProgress.percent} className="h-1.5 mb-4" />
            <div className="space-y-2">
              {documentsForType.map((docName) => {
                const staged = stagedDocs[docName];
                const isAttached = Boolean(staged?.file || staged?.fileUrl);
                const isCustom = customDocSet.has(docName);
                return (
                  <div
                    key={docName}
                    className={cn(
                      'group rounded-xl border p-3 text-sm transition-all duration-200',
                      isAttached
                        ? 'border-emerald-300 bg-emerald-50/60 dark:border-emerald-800 dark:bg-emerald-950/20'
                        : 'border-slate-200 dark:border-slate-700 hover:border-blue-300 dark:hover:border-blue-700 hover:shadow-sm'
                    )}
                  >
                    <div className="flex items-center gap-2.5">
                      <div
                        className={cn(
                          'w-8 h-8 rounded-lg flex items-center justify-center shrink-0 transition-colors',
                          isAttached
                            ? 'bg-emerald-100 text-emerald-600 dark:bg-emerald-900/40 dark:text-emerald-400'
                            : 'bg-slate-100 text-slate-400 dark:bg-slate-800 dark:text-slate-500'
                        )}
                      >
                        {isAttached ? <CheckCircle2 className="w-4 h-4" /> : <FileText className="w-4 h-4" />}
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-1.5 min-w-0">
                          <span className="font-semibold text-slate-900 dark:text-slate-50 truncate leading-tight">
                            {docName}
                          </span>
                          {isCustom ? (
                            <Badge variant="outline" className="text-[10px] px-1 py-0 border-violet-300 text-violet-600 dark:border-violet-700 dark:text-violet-400 shrink-0">
                              Custom
                            </Badge>
                          ) : null}
                        </div>
                        {isAttached ? (
                          <div className="flex items-center gap-1.5 text-xs text-slate-500 min-w-0 mt-0.5">
                            {staged?.source === 'ISF' ? (
                              <Badge variant="outline" className="text-[10px] px-1 py-0 border-blue-300 text-blue-600 dark:border-blue-700 dark:text-blue-400 shrink-0">
                                ISF
                              </Badge>
                            ) : null}
                            <span className="truncate">{staged?.file?.name || staged?.sourceTitle}</span>
                          </div>
                        ) : (
                          <div className="text-xs text-slate-400 dark:text-slate-500 mt-0.5">Not attached yet</div>
                        )}
                      </div>
                      {isAttached || isCustom ? (
                        <Button
                          type="button"
                          variant="ghost"
                          size="sm"
                          className="text-slate-400 hover:text-red-600 hover:bg-red-50 dark:hover:bg-red-950/20 h-7 w-7 p-0 shrink-0"
                          title={isAttached ? 'Remove file' : 'Remove document'}
                          onClick={() =>
                            isCustom && !isAttached ? removeCustomDoc(docName) : removeStagedDoc(docName)
                          }
                        >
                          <X className="w-3.5 h-3.5" />
                        </Button>
                      ) : null}
                    </div>
                    {!isAttached ? (
                      <div className="flex items-center gap-2 mt-2.5 pl-[42px]">
                        <Button
                          type="button"
                          variant="outline"
                          size="sm"
                          className="h-7 px-2.5 text-xs rounded-lg border-blue-200 text-blue-700 hover:bg-blue-50 hover:border-blue-300 dark:border-blue-800 dark:text-blue-400 dark:hover:bg-blue-950/30"
                          onClick={() => openISFBrowser(docName)}
                        >
                          <FolderSearch className="w-3.5 h-3.5 mr-1" />
                          Import from ISF
                        </Button>
                        <Button
                          type="button"
                          variant="outline"
                          size="sm"
                          className="h-7 px-2.5 text-xs rounded-lg text-slate-600 dark:text-slate-300"
                          onClick={() => openFilePicker(docName)}
                        >
                          <Upload className="w-3.5 h-3.5 mr-1" />
                          Attach
                        </Button>
                      </div>
                    ) : null}
                  </div>
                );
              })}
            </div>
            <Button
              type="button"
              variant="outline"
              className="w-full mt-3 h-9 text-xs rounded-xl border-dashed border-slate-300 text-slate-500 hover:border-blue-400 hover:text-blue-600 hover:bg-blue-50/50 dark:border-slate-600 dark:text-slate-400 dark:hover:border-blue-600 dark:hover:text-blue-400 dark:hover:bg-blue-950/20"
              onClick={() => setAddDocOpen(true)}
            >
              <Plus className="w-3.5 h-3.5 mr-1.5" />
              Add Document
            </Button>
            <p className="text-xs text-slate-500 mt-3">
              Import documents from the Investigator Site File (ISF) or upload them locally. Documents are optional at
              this stage — the package is saved as a draft and files can be added later.
            </p>
          </CardContent>
        </Card>
      </div>
      <input ref={fileInputRef} type="file" className="hidden" onChange={onFilePicked} />
    </div>
  );

  const reviewRow = (label, value, valueClass) => (
    <div
      key={label}
      className="flex items-start justify-between gap-6 py-2.5 border-b border-slate-100 dark:border-slate-800 last:border-b-0 text-sm"
    >
      <span className="text-[13px] text-slate-500 dark:text-slate-400 font-medium shrink-0">{label}</span>
      <span className={cn('text-right font-semibold text-slate-900 dark:text-slate-50 break-words min-w-0 leading-snug', valueClass)}>
        {value}
      </span>
    </div>
  );

  const reviewCardHeader = (Icon, iconClass, title, subtitle, right = null) => (
    <div className="px-5 sm:px-6 py-4 border-b border-slate-100 dark:border-slate-800 bg-slate-50/70 dark:bg-slate-800/40 flex items-center gap-3">
      <div className={cn('w-9 h-9 rounded-lg text-white flex items-center justify-center shadow-sm shrink-0', iconClass)}>
        <Icon className="w-4 h-4" />
      </div>
      <div className="flex-1 min-w-0">
        <h4 className="text-sm font-bold text-slate-900 dark:text-slate-50 leading-tight">{title}</h4>
        <p className="text-xs text-slate-500 dark:text-slate-400 mt-0.5 truncate">{subtitle}</p>
      </div>
      {right}
    </div>
  );

  const renderStep5_review = () => {
    const allDocsAttached = docProgress.uploaded === docProgress.total;
    return (
      <div className="space-y-6">
        {renderStepHeading(CheckCircle, selectedType?.name, 'Review & Submit', 'Confirm everything looks correct, then create the package.')}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          <Card className="border-slate-200 dark:border-slate-700 rounded-2xl overflow-hidden shadow-sm h-fit">
            {reviewCardHeader(
              ClipboardList,
              'bg-blue-600 shadow-blue-500/30',
              'Summary',
              'Package scope and settings'
            )}
            <CardContent className="p-5 sm:p-6 pt-3 sm:pt-3">
              {reviewRow(
                'Category',
                <Badge variant="outline" className="font-semibold text-xs border-blue-200 text-blue-700 bg-blue-50 dark:border-blue-800 dark:text-blue-400 dark:bg-blue-950/30">
                  {selectedType?.category}
                </Badge>
              )}
              {reviewRow('Notification Type', selectedType?.name)}
              {reviewRow('Study', studyName || studyId)}
              {reviewRow('Site', siteName || siteId)}
              {reviewRow('IRB / Ethics Board', irb?.name || '—')}
              {reviewRow('Package Name', packageName || '—')}
              {reviewRow('Priority', priority)}
              {reviewRow('Expected Submission', expectedSubmissionDate || '—')}
              {reviewRow('Response Timeline', `${selectedType?.dueDays ?? '—'} days`)}
              {reviewRow(
                'Documents Attached',
                <span className={cn('inline-flex items-center gap-1.5', allDocsAttached ? 'text-emerald-600 dark:text-emerald-400' : 'text-amber-600 dark:text-amber-400')}>
                  {allDocsAttached ? <CheckCircle2 className="w-3.5 h-3.5" /> : <AlertCircle className="w-3.5 h-3.5" />}
                  {docProgress.uploaded} of {docProgress.total}
                </span>
              )}
            </CardContent>
          </Card>
          <Card className="border-slate-200 dark:border-slate-700 rounded-2xl overflow-hidden shadow-sm h-fit">
            {reviewCardHeader(
              FileText,
              'bg-indigo-600 shadow-indigo-500/30',
              'Notification Details',
              selectedType?.name || 'Form data',
              <Badge variant="outline" className="text-[11px] font-mono shrink-0 border-slate-200 text-slate-500 dark:border-slate-700 dark:text-slate-400">
                {(selectedType?.fields || []).filter((fk) => String(formData[fk] ?? '').trim() !== '').length}/{(selectedType?.fields || []).length} filled
              </Badge>
            )}
            <CardContent className="p-5 sm:p-6 pt-3 sm:pt-3">
              {(selectedType?.fields || []).map((fk) => {
                const v = formData[fk];
                const hasValue = v !== undefined && String(v).trim() !== '';
                return reviewRow(
                  fieldLabel(selectedType, fk),
                  hasValue ? String(v) : 'not provided',
                  hasValue ? undefined : 'font-normal italic text-slate-400 dark:text-slate-500'
                );
              })}
            </CardContent>
          </Card>
        </div>
        {!allDocsAttached ? (
          <div className="flex items-start gap-2.5 text-sm text-amber-800 dark:text-amber-300 bg-amber-50/80 dark:bg-amber-950/30 border border-amber-200 dark:border-amber-900 rounded-xl px-4 py-3">
            <AlertCircle className="w-4 h-4 shrink-0 mt-0.5" />
            <span>
              {docProgress.total - docProgress.uploaded} supporting document(s) not attached yet — the package will be created
              as a draft and documents can be added later.
            </span>
          </div>
        ) : null}
      </div>
    );
  };

  const renderCurrentStep = () => {
    switch (step) {
      case 1: return renderStep1_category();
      case 2: return renderStep2_type();
      case 3: return renderStep3_context();
      case 4: return renderStep4_formAndDocs();
      case 5: return renderStep5_review();
      default: return renderStep1_category();
    }
  };

  return (
    <NotificationFlowLayout>
      {isSubmitting ? (
        <div className="fixed inset-0 z-[200] bg-black/30 backdrop-blur-[1px] flex items-center justify-center">
          <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-lg shadow-xl p-6 w-[min(520px,92vw)]">
            <div className="flex items-center gap-3">
              <Loader2 className="w-5 h-5 animate-spin text-slate-700 dark:text-slate-200" />
              <div className="font-semibold text-slate-900 dark:text-slate-50">
                {isEditing ? 'Saving notification package…' : 'Creating notification package…'}
              </div>
            </div>
            <div className="mt-3 text-sm text-slate-600 dark:text-slate-300">Please wait. Do not close this page.</div>
            <div className="mt-4">
              <Progress value={uploadOverallProgress} className="h-2" />
              <div className="mt-2 text-xs text-slate-500 dark:text-slate-400">{uploadOverallProgress}% uploaded</div>
            </div>
          </div>
        </div>
      ) : null}

      {/* Step Indicator */}
      <div className="pb-6 mb-8 border-b border-slate-200 dark:border-slate-800">
        <div className="flex items-center justify-between gap-3">
          <div className="flex items-center gap-2 flex-1 min-w-0">
            {WIZARD_STEPS.map((s, index) => {
              const canJump = s.id === 1 || (s.id === 2 ? Boolean(categoryId) : Boolean(typeId));
              return (
              <React.Fragment key={s.id}>
                <div
                  className={cn('flex items-center gap-2 min-w-0', canJump && 'cursor-pointer')}
                  onClick={() => {
                    if (canJump && !isSubmitting) setStep(s.id);
                  }}
                >
                  <div
                    className={cn(
                      'w-8 h-8 rounded-full flex items-center justify-center text-sm font-bold transition-all duration-500 shadow-sm shrink-0',
                      step === s.id
                        ? 'bg-blue-600 text-white ring-4 ring-blue-500/10'
                        : step > s.id
                          ? 'bg-emerald-500 text-white'
                          : 'bg-slate-100 text-slate-400 dark:bg-slate-800'
                    )}
                  >
                    {step > s.id ? <CheckCircle className="w-4 h-4" /> : s.id}
                  </div>
                  <div className="hidden lg:flex flex-col min-w-0">
                    <span
                      className={cn(
                        'text-[9px] font-bold uppercase tracking-[0.1em] mb-0.5',
                        step === s.id ? 'text-blue-600' : 'text-slate-400'
                      )}
                    >
                      Step {s.id}
                    </span>
                    <span
                      className={cn(
                        'text-xs font-bold leading-none whitespace-nowrap',
                        step === s.id ? 'text-slate-900 dark:text-slate-50' : 'text-slate-400'
                      )}
                    >
                      {s.name}
                    </span>
                  </div>
                </div>
                {index < WIZARD_STEPS.length - 1 && (
                  <div className="h-0.5 flex-1 min-w-[8px] max-w-14 bg-slate-100 dark:bg-slate-800" />
                )}
              </React.Fragment>
              );
            })}
          </div>
          <Button
            type="button"
            variant="ghost"
            onClick={async () => {
              const confirmed = window.confirm('Discard this notification package and return to list?');
              if (!confirmed) return;
              await clearDraft();
              onCancel?.();
            }}
            className="text-slate-500 hover:text-red-600 hover:bg-red-50 dark:text-slate-400 dark:hover:text-red-400 dark:hover:bg-red-950/20 px-4 shrink-0"
          >
            <X className="w-4 h-4 mr-2" />
            Cancel
          </Button>
        </div>
      </div>

      {/* Content */}
      <div className="space-y-8">
        <div className="animate-in fade-in slide-in-from-bottom-4 duration-500" key={step}>
          {renderCurrentStep()}
        </div>

        {/* Navigation */}
        <div className="flex items-center justify-between">
          <Button type="button" variant="outline" onClick={handlePrevious} disabled={isSubmitting} className="flex items-center gap-2">
            <ArrowLeft className="w-4 h-4" />
            {step === 1 ? (isEditing ? 'Back to Packages' : 'Back to Submission Type') : 'Previous'}
          </Button>
          <div className="flex items-center gap-3">
            {step === WIZARD_STEPS.length ? (
              <Button
                type="button"
                onClick={handleCreate}
                disabled={isSubmitting || !selectedType || !studyId || !siteId || !irb?.id}
                className="flex items-center gap-2 bg-green-600 hover:bg-green-700"
              >
                {isSubmitting ? (
                  <>
                    <Loader2 className="w-4 h-4 animate-spin" />
                    {isEditing ? 'Saving…' : 'Creating…'}
                  </>
                ) : (
                  <>
                    <Save className="w-4 h-4" />
                    {isEditing ? 'Save Package' : 'Create Package'}
                  </>
                )}
              </Button>
            ) : (
              <Button
                type="button"
                onClick={handleNext}
                disabled={(step === 1 && !categoryId) || (step === 2 && !typeId)}
                className="flex items-center gap-2 bg-emerald-600 hover:bg-emerald-700"
              >
                Next
                <ArrowRight className="w-4 h-4" />
              </Button>
            )}
          </div>
        </div>
      </div>

      {/* Add custom document dialog */}
      <Dialog open={addDocOpen} onOpenChange={setAddDocOpen}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>Add Document</DialogTitle>
            <DialogDescription>
              Add your own document to this notification package. You can then import it from the ISF or attach a
              local file.
            </DialogDescription>
          </DialogHeader>
          <div className="py-2">
            <Input
              placeholder="e.g. Sponsor Correspondence"
              value={newDocName}
              onChange={(e) => setNewDocName(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter') {
                  e.preventDefault();
                  handleAddCustomDoc();
                }
              }}
              autoFocus
            />
          </div>
          <DialogFooter className="flex gap-2 sm:justify-end">
            <Button variant="ghost" onClick={() => setAddDocOpen(false)}>
              Cancel
            </Button>
            <Button onClick={handleAddCustomDoc} disabled={!newDocName.trim()} className="bg-blue-600 hover:bg-blue-700">
              <Plus className="w-4 h-4 mr-1" />
              Add Document
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* ISF Document Browser Modal */}
      <Dialog
        open={showISFBrowser}
        onOpenChange={(open) => {
          if (!open) closeISFBrowser();
          else setShowISFBrowser(true);
        }}
      >
        <DialogContent className="max-w-5xl p-0 gap-0 overflow-hidden">
          <DialogHeader className="px-6 pt-5 pb-4 border-b border-slate-200 bg-white">
            <DialogTitle className="text-lg font-semibold text-slate-900">ISF Document Browser</DialogTitle>
            <DialogDescription className="text-sm text-slate-500">
              Browse ISF folders and import a document into {selectedDocForISF || 'the selected requirement'}.
            </DialogDescription>
          </DialogHeader>
          <ISFDocumentBrowser
            key={isfBrowserKey}
            onImport={handleISFImport}
            onClose={closeISFBrowser}
          />
        </DialogContent>
      </Dialog>
    </NotificationFlowLayout>
  );
};

/**
 * Loads the notification template registry (MongoDB via /notification-templates,
 * with the built-in constants as fallback) before rendering the wizard.
 */
const NotificationPackageWizard = (props) => {
  const [registry, setRegistry] = useState(_registryCache);

  useEffect(() => {
    if (registry) return undefined;
    let alive = true;
    loadNotificationRegistry().then((r) => {
      if (alive) setRegistry(r);
    });
    return () => {
      alive = false;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  if (!registry) {
    return (
      <NotificationFlowLayout>
        <div className="flex items-center justify-center gap-2 py-20 text-sm text-slate-500 dark:text-slate-400">
          <Loader2 className="w-5 h-5 animate-spin" />
          Loading notification templates…
        </div>
      </NotificationFlowLayout>
    );
  }
  return <NotificationWizardInner {...props} registry={registry} />;
};

export default NotificationPackageWizard;
